BOOK.add({
  subject: "reas",
  id: "reas-06",
  title: "दिशा एवं दूरी, क्रम एवं रैंकिंग, बैठक व्यवस्था",
  notes: "\n    <h3>भाग 1 — दिशा एवं दूरी</h3>\n    <p>चार मुख्य दिशाएँ — उत्तर (N), दक्षिण (S), पूर्व (E), पश्चिम (W) और चार उप-दिशाएँ — उत्तर-पूर्व (ईशान), दक्षिण-पूर्व (आग्नेय), दक्षिण-पश्चिम (नैऋत्य), उत्तर-पश्चिम (वायव्य)। कागज़ पर सदैव <b>ऊपर उत्तर, नीचे दक्षिण, दाएँ पूर्व, बाएँ पश्चिम</b> मानें।</p>\n    <table>\n      <tr><td>उत्तर-पश्चिम (NW)</td><td>उत्तर (N)</td><td>उत्तर-पूर्व (NE)</td></tr>\n      <tr><td>पश्चिम (W)</td><td>केंद्र</td><td>पूर्व (E)</td></tr>\n      <tr><td>दक्षिण-पश्चिम (SW)</td><td>दक्षिण (S)</td><td>दक्षिण-पूर्व (SE)</td></tr>\n    </table>\n    <h4>मुड़ने के नियम</h4>\n    <table>\n      <tr><th>वर्तमान मुख</th><th>दाएँ मुड़ने पर</th><th>बाएँ मुड़ने पर</th><th>पीछे मुड़ने पर</th></tr>\n      <tr><td>उत्तर</td><td>पूर्व</td><td>पश्चिम</td><td>दक्षिण</td></tr>\n      <tr><td>पूर्व</td><td>दक्षिण</td><td>उत्तर</td><td>पश्चिम</td></tr>\n      <tr><td>दक्षिण</td><td>पश्चिम</td><td>पूर्व</td><td>उत्तर</td></tr>\n      <tr><td>पश्चिम</td><td>उत्तर</td><td>दक्षिण</td><td>पूर्व</td></tr>\n    </table>\n    <ul>\n      <li><b>दाएँ मुड़ना</b> = 90° दक्षिणावर्त (घड़ी की दिशा में); <b>बाएँ मुड़ना</b> = 90° वामावर्त।</li>\n      <li>कोण से मुड़ना: उत्तर को 0° मानकर दक्षिणावर्त जोड़ें, वामावर्त घटाएँ; 360 से भाग का शेष लें। 0° उत्तर, 45° NE, 90° पूर्व, 135° SE, 180° दक्षिण, 225° SW, 270° पश्चिम, 315° NW।</li>\n      <li>270° वामावर्त = 90° दक्षिणावर्त; 270° दक्षिणावर्त = 90° वामावर्त।</li>\n    </ul>\n    <h4>दूरी — निर्देशांक विधि</h4>\n    <p>पूर्व को +x, पश्चिम को −x, उत्तर को +y, दक्षिण को −y लिखें। अंतिम बिंदु (x, y) निकालें; प्रारंभ से न्यूनतम दूरी = √(x² + y²)। दिशा: x और y के चिह्न से (x > 0, y > 0 ⇒ उत्तर-पूर्व)।</p>\n    <p><b>हल किया उदाहरण:</b> रवि 10 m दक्षिण, बाएँ मुड़कर 20 m, फिर बाएँ 10 m, फिर दाएँ 5 m चलता है। — (0, −10) → दक्षिण की ओर से बाएँ = पूर्व: (20, −10) → पूर्व से बाएँ = उत्तर: (20, 0) → उत्तर से दाएँ = पूर्व: (25, 0)। उत्तर: <b>25 m पूर्व</b>।</p>\n    <div class=\"tip\">पाइथागोरस त्रिक याद रखें: (3, 4, 5), (6, 8, 10), (5, 12, 13), (8, 15, 17), (7, 24, 25), (9, 12, 15), (12, 16, 20), (20, 21, 29)। इनके गुणज भी त्रिक होते हैं।</div>\n    <h4>छाया (Shadow) आधारित प्रश्न</h4>\n    <ul>\n      <li>सूर्य सुबह पूर्व में ⇒ छाया <b>पश्चिम</b> की ओर; शाम को सूर्य पश्चिम में ⇒ छाया <b>पूर्व</b> की ओर।</li>\n      <li>सुबह सूर्य की ओर मुँह = पूर्व की ओर मुँह ⇒ बायाँ हाथ उत्तर, दायाँ दक्षिण।</li>\n      <li>सुबह छाया दाईं ओर ⇒ दायाँ = पश्चिम ⇒ व्यक्ति का मुख दक्षिण की ओर। सुबह छाया बाईं ओर ⇒ मुख उत्तर की ओर।</li>\n      <li>दोपहर ठीक 12 बजे के प्रश्न सामान्यतः नहीं पूछे जाते (छाया लगभग नहीं बनती)।</li>\n    </ul>\n    <h4>दिशा-परिवर्तन (नाम बदलना)</h4>\n    <p>\"यदि दक्षिण-पूर्व को उत्तर कहा जाए…\" — दोनों दिशाओं का कोण-अंतर निकालें (SE = 135°, N = 0° ⇒ सब दिशाएँ 135° वामावर्त घूमीं) और वही घुमाव पूछी गई दिशा पर लगाएँ। पश्चिम (270°) − 135° = 135° = दक्षिण-पूर्व।</p>\n\n    <h3>भाग 2 — क्रम एवं रैंकिंग</h3>\n    <table>\n      <tr><th>स्थिति</th><th>सूत्र</th></tr>\n      <tr><td>बाएँ से स्थान + दाएँ से स्थान ज्ञात</td><td>कुल = बाएँ + दाएँ − 1</td></tr>\n      <tr><td>कुल और एक ओर से स्थान ज्ञात</td><td>दूसरी ओर से = कुल − ज्ञात स्थान + 1</td></tr>\n      <tr><td>दोनों छोरों से समान स्थान</td><td>कुल = 2 × स्थान − 1 (कुल विषम ही होगा)</td></tr>\n      <tr><td>दो व्यक्तियों के बीच (एक ही ओर से स्थान)</td><td>बीच वाले = बड़ा स्थान − छोटा स्थान − 1</td></tr>\n      <tr><td>अदला-बदली (स्थान परिवर्तन)</td><td>नया स्थान दूसरे व्यक्ति का पुराना स्थान होता है — उसी से कुल निकालें</td></tr>\n    </table>\n    <p><b>हल किया उदाहरण:</b> 30 की पंक्ति में A बाएँ से 7वाँ, B दाएँ से 12वाँ। B बाएँ से = 30 − 12 + 1 = 19वाँ; बीच में = 19 − 7 − 1 = <b>11</b>।</p>\n    <p><b>हल किया उदाहरण:</b> A बाएँ से 10वाँ, B दाएँ से 10वाँ। अदला-बदली के बाद A बाएँ से 15वाँ हो गया ⇒ B का पुराना स्थान बाएँ से 15वाँ और दाएँ से 10वाँ ⇒ कुल = 15 + 10 − 1 = <b>24</b>।</p>\n    <h4>तुलना (लंबाई/भार/आयु) वाले प्रश्न</h4>\n    <p>हर कथन को चिह्न से लिखें (A > B) और एक ही रेखा में जोड़ें: \"A, B से लंबा; B, C से लंबा; D, A से लंबा; E, C से छोटा\" ⇒ D > A > B > C > E।</p>\n\n    <h3>भाग 3 — बैठक व्यवस्था</h3>\n    <h4>रैखिक (पंक्ति) व्यवस्था</h4>\n    <ul>\n      <li><b>उत्तर की ओर मुख:</b> व्यक्ति का दायाँ = हमारा दायाँ (पूर्व)।</li>\n      <li><b>दक्षिण की ओर मुख:</b> व्यक्ति का दायाँ = हमारा बायाँ। यदि सभी एक ही ओर मुख किए हैं, तो उन्हीं के \"बाएँ-दाएँ\" के अनुसार क्रम लिखें।</li>\n      <li>पहले निश्चित तथ्य (छोर पर कौन, ठीक बगल में कौन) रखें; फिर \"बीच में\", \"से दूसरा\" जैसे कथन।</li>\n    </ul>\n    <h4>वृत्ताकार व्यवस्था</h4>\n    <ul>\n      <li><b>केंद्र की ओर मुख:</b> बायाँ = दक्षिणावर्त (clockwise) पड़ोसी, दायाँ = वामावर्त पड़ोसी।</li>\n      <li><b>केंद्र से बाहर मुख:</b> बायाँ = वामावर्त, दायाँ = दक्षिणावर्त।</li>\n      <li>n व्यक्ति (n सम) हों तो \"ठीक सामने\" वाला n/2 स्थान दूर होता है।</li>\n    </ul>\n    <p><b>हल किया उदाहरण:</b> 6 मित्र केंद्र की ओर मुख करके बैठे; B, A के ठीक बाएँ; C, B के ठीक बाएँ; D, A के ठीक सामने; E, D और F के बीच। ⇒ दक्षिणावर्त क्रम: A, B, C, D, E, F। F के ठीक बाएँ (दक्षिणावर्त अगला) = A।</p>\n    <div class=\"tip\">बैठक व्यवस्था में हमेशा एक चित्र बनाएँ — रैखिक में 1, 2, 3 … खाने, वृत्ताकार में घड़ी जैसा गोला। \"ठीक बगल\" (immediate) और \"बगल में कहीं\" (not immediate) में अंतर ध्यान से पढ़ें।</div>\n\n    <h3>भाग 4 — और हल किए उदाहरण</h3>\n    <p><b>(क) दिशा:</b> एक व्यक्ति 20 m उत्तर, दाएँ 15 m, दाएँ 40 m, दाएँ 15 m चलता है। निर्देशांक: (0, 20) → (15, 20) → (15, −20) → (0, −20)। प्रारंभ से <b>20 m दक्षिण</b>। ध्यान दें — पूर्व-पश्चिम के 15-15 m कट गए, उत्तर 20 और दक्षिण 40 का अंतर 20 दक्षिण बचा।</p>\n    <p><b>(ख) रैंकिंग:</b> कतार में X आगे से 9वाँ, Y पीछे से 9वाँ, X आगे है और बीच में 4 व्यक्ति। Y का आगे से स्थान = 9 + 4 + 1 = 14; कुल = 14 + 9 − 1 = <b>22</b>। यदि प्रश्न में यह न बताया जाता कि X आगे है, तो दूसरी संभावना (Y आगे) से कुल 9 + 9 − 4 − 2 = 12 भी हो सकता था — इसलिए शर्तें ध्यान से पढ़ें।</p>\n    <p><b>(ग) बैठक:</b> A, B, C, D, E उत्तरमुखी; E, C के ठीक दाएँ; B, E के ठीक दाएँ; D दाएँ छोर पर; A, D के ठीक बाएँ नहीं। C-E-B एक खंड है; D स्थान 5 पर; यदि खंड 2-3-4 पर हो तो A स्थान 1 पर (D के बगल में नहीं ✓), यदि खंड 1-2-3 पर हो तो A स्थान 4 पर (D के ठीक बाएँ ✗)। अतः क्रम <b>A C E B D</b>।</p>\n  ",
  extra: "\n    <h3>गहन तथ्य / ट्रिक्स</h3>\n    <ul>\n      <li><b>उलटी दिशा:</b> यदि स्कूल घर से उत्तर-पूर्व में है, तो घर स्कूल से दक्षिण-पश्चिम में है। सदैव 180° घुमा दें।</li>\n      <li><b>दो दाएँ मुड़ने</b> = पीछे मुड़ना; <b>दाएँ फिर बाएँ</b> = मूल दिशा। तीन दाएँ = एक बाएँ।</li>\n      <li><b>शुद्ध घुमाव गिनें:</b> दाएँ = +1, बाएँ = −1; कुल योग को 4 से भाग दें — शेष 0 = मूल दिशा, 1 = दाएँ, 2 = पीछे, 3 = बाएँ।</li>\n      <li><b>सीढ़ीनुमा पथ:</b> 1 km उत्तर, 1 km पूर्व, 1 km दक्षिण, 1 km पूर्व — उत्तर-दक्षिण कट जाते हैं; शुद्ध विस्थापन 2 km पूर्व।</li>\n      <li><b>विपरीत दिशाओं में चलना:</b> दूरी जुड़ती है (5 + 7 = 12); समकोण दिशाओं में चलना: पाइथागोरस (9, 12 ⇒ 15)।</li>\n      <li><b>छाया का नियम (भारत):</b> सुबह छाया पश्चिम, शाम को पूर्व। \"सूर्योदय के समय आमने-सामने खड़े\" प्रश्नों में एक का मुख उत्तर तो दूसरे का दक्षिण होगा यदि छाया बाएँ-दाएँ पड़ रही हो।</li>\n      <li><b>रैंकिंग में अतिव्यापन:</b> यदि दो व्यक्तियों के स्थानों का योग कुल से अधिक हो, तो वे एक-दूसरे को पार कर चुके हैं; बीच वाले = (योग − कुल − 2)।</li>\n      <li><b>दोनों ओर से समान स्थान</b> केवल विषम कुल संख्या में संभव — 25 में 13वाँ, 41 में 21वाँ।</li>\n      <li><b>वृत्त में n व्यक्तियों की व्यवस्थाएँ:</b> (n − 1)! (जैसे 5 व्यक्ति ⇒ 24 अलग व्यवस्थाएँ) — इसलिए पहला व्यक्ति कहीं भी रखकर बाकी उसके सापेक्ष रखें।</li>\n      <li><b>उत्तर की ओर मुख किए पंक्ति में</b> \"बाएँ छोर\" = पश्चिम छोर; दक्षिण की ओर मुख किए पंक्ति में \"बाएँ छोर\" = पूर्व छोर।</li>\n      <li><b>दिशाओं के संस्कृत नाम:</b> ईशान (उत्तर-पूर्व), आग्नेय (दक्षिण-पूर्व), नैऋत्य (दक्षिण-पश्चिम), वायव्य (उत्तर-पश्चिम) — कुछ परीक्षाओं में इन्हीं नामों से प्रश्न आते हैं।</li>\n      <li><b>घड़ी और दिशा:</b> यदि घड़ी का 12 उत्तर की ओर हो तो 3 पूर्व, 6 दक्षिण, 9 पश्चिम; घंटे की सुई का हर घंटा 30° घूमता है।</li>\n      <li><b>तुलना-श्रृंखला में अधूरी जानकारी:</b> यदि दो व्यक्तियों की आपस में तुलना न हो (A > B, A > C), तो B और C का क्रम अनिश्चित है — ऐसे में \"निर्धारित नहीं\" विकल्प पर विचार करें।</li>\n      <li><b>\"कम से कम कितनी दूरी\"</b> का अर्थ सदैव सीधी रेखा (विस्थापन) है, चली गई कुल दूरी नहीं।</li>\n    </ul>\n  ",
  questions: [
    {"q":"राम 5 km उत्तर चलता है, फिर दाएँ मुड़कर 3 km, फिर दाएँ मुड़कर 5 km चलता है। वह प्रारंभिक बिंदु से कितनी दूर और किस दिशा में है?","o":["3 km पश्चिम","13 km उत्तर","3 km पूर्व","5 km दक्षिण"],"a":2,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख उत्तर, 5 km → (0, 5)।<br>चरण 2: दाएँ मुड़ा → मुख पूर्व, 3 km → (3, 5)।<br>चरण 3: दाएँ मुड़ा → मुख दक्षिण, 5 km → (3, 0)।<br>चरण 4: अंतिम स्थिति (3, 0) → y = 0, x = +3 → प्रारंभ से 3 km पूर्व।<br>अतः उत्तर = <b>3 km पूर्व</b><br><b>ध्यान दें:</b> उत्तर-दक्षिण की 5-5 km दूरी आपस में कट जाती है।"},
    {"q":"एक व्यक्ति 6 km पूर्व और फिर 8 km उत्तर चलता है। प्रारंभिक बिंदु से उसकी न्यूनतम दूरी कितनी है?","o":["10 km","14 km","12 km","2 km"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: पूर्व 6 km → (6, 0)।<br>चरण 2: उत्तर 8 km → (6, 8)।<br>चरण 3: न्यूनतम दूरी (पाइथागोरस) = √(6² + 8²) = √(36 + 64) = √100 = 10 km।<br>अतः उत्तर = <b>10 km</b><br><b>शॉर्टकट:</b> 6-8-10 (3-4-5 का दुगुना) त्रिक याद रखें।<br><b>ध्यान दें:</b> 14 km कुल चली गई दूरी है, न्यूनतम दूरी नहीं।"},
    {"q":"एक व्यक्ति 6 km पूर्व और फिर 8 km उत्तर चलता है। अब वह प्रारंभिक बिंदु से किस दिशा में है?","o":["उत्तर-पश्चिम","दक्षिण-पूर्व","दक्षिण-पश्चिम","उत्तर-पूर्व"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: पूर्व 6 km → (6, 0); उत्तर 8 km → (6, 8)।<br>चरण 2: x धनात्मक (पूर्व) और y धनात्मक (उत्तर)।<br>चरण 3: अतः दिशा = उत्तर-पूर्व।<br>अतः उत्तर = <b>उत्तर-पूर्व</b>"},
    {"q":"सूर्योदय के समय एक व्यक्ति सूर्य की ओर मुँह करके खड़ा है। उसकी बाईं ओर कौन-सी दिशा है?","o":["दक्षिण","उत्तर","पश्चिम","पूर्व"],"a":1,"e":"<b>हल:</b><br>चरण 1: सूर्योदय के समय सूर्य पूर्व में → व्यक्ति का मुख पूर्व।<br>चरण 2: पूर्व की ओर मुँह हो तो — दायाँ = दक्षिण, बायाँ = उत्तर, पीछे = पश्चिम।<br>अतः उत्तर = <b>उत्तर</b>"},
    {"q":"शाम के समय एक व्यक्ति की छाया उसके ठीक पीछे पड़ रही है। उसका मुख किस दिशा में है?","o":["पूर्व","पश्चिम","उत्तर","दक्षिण"],"a":1,"e":"<b>हल:</b><br>चरण 1: शाम को सूर्य पश्चिम में → छाया पूर्व की ओर बनती है।<br>चरण 2: छाया ठीक पीछे है → पीछे = पूर्व।<br>चरण 3: पीछे पूर्व हो तो मुख = पश्चिम।<br>अतः उत्तर = <b>पश्चिम</b>"},
    {"q":"सुबह के समय एक व्यक्ति की छाया उसकी दाईं ओर पड़ रही है। उसका मुख किस दिशा में है?","o":["उत्तर","पूर्व","पश्चिम","दक्षिण"],"a":3,"e":"<b>हल:</b><br>चरण 1: सुबह सूर्य पूर्व में → छाया पश्चिम की ओर।<br>चरण 2: छाया दाईं ओर → दायाँ हाथ = पश्चिम।<br>चरण 3: जिसका दायाँ पश्चिम हो, उसका मुख दक्षिण होता है (दक्षिण मुख: दायाँ = पश्चिम, बायाँ = पूर्व)।<br>अतः उत्तर = <b>दक्षिण</b>"},
    {"q":"एक व्यक्ति पश्चिम की ओर मुँह करके खड़ा है। वह 90° दक्षिणावर्त घूमता है, फिर 180° वामावर्त। अब उसका मुख किस दिशा में है?","o":["दक्षिण","उत्तर","पूर्व","पश्चिम"],"a":0,"e":"<b>हल:</b><br>चरण 1: प्रारंभिक मुख = पश्चिम।<br>चरण 2: 90° दक्षिणावर्त → पश्चिम से उत्तर।<br>चरण 3: 180° वामावर्त (या कोई भी दिशा, 180° = पलटना) → उत्तर से दक्षिण।<br>अतः उत्तर = <b>दक्षिण</b><br><b>शॉर्टकट:</b> कुल घुमाव = 90° दक्षिणावर्त − 180° = 90° वामावर्त; पश्चिम से 90° वामावर्त = दक्षिण।"},
    {"q":"उत्तर की ओर मुँह किए व्यक्ति 135° दक्षिणावर्त घूमता है। अब उसका मुख किस ओर है?","o":["उत्तर-पश्चिम","दक्षिण-पश्चिम","दक्षिण-पूर्व","उत्तर-पूर्व"],"a":2,"e":"<b>हल:</b><br>नियम: दक्षिणावर्त (घड़ी की दिशा) = उ → उपू → पू → दपू → द → दप → प → उप → उ (हर कदम 45°)।<br>चरण 1: प्रारंभिक मुख = उत्तर।<br>चरण 2: 135° = 3 × 45° → उत्तर → उत्तर-पूर्व (45°) → पूर्व (90°) → दक्षिण-पूर्व (135°)।<br>अतः उत्तर = <b>दक्षिण-पूर्व</b>"},
    {"q":"रवि 10 m दक्षिण चलता है, बाएँ मुड़कर 20 m, फिर बाएँ मुड़कर 10 m, फिर दाएँ मुड़कर 5 m चलता है। वह प्रारंभ से कितनी दूर और किस दिशा में है?","o":["25 m पश्चिम","35 m पूर्व","15 m पूर्व","25 m पूर्व"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख दक्षिण, 10 m → (0, −10)।<br>चरण 2: बाएँ मुड़ा → मुख पूर्व (दक्षिण मुख का बायाँ = पूर्व), 20 m → (20, −10)।<br>चरण 3: बाएँ मुड़ा → मुख उत्तर, 10 m → (20, 0)।<br>चरण 4: दाएँ मुड़ा → मुख पूर्व, 5 m → (25, 0)।<br>चरण 5: अंतिम (25, 0) → 25 m पूर्व।<br>अतः उत्तर = <b>25 m पूर्व</b><br><b>ध्यान दें:</b> दक्षिण की ओर चलते समय \"बायाँ\" पूर्व होता है, पश्चिम नहीं।"},
    {"q":"A, B के 5 km उत्तर में है और C, B के 12 km पूर्व में है। A और C के बीच की दूरी कितनी है?","o":["17 km","7 km","13 km","15 km"],"a":2,"e":"<b>हल:</b><br>निर्देशांक: B = (0, 0)।<br>चरण 1: A, B के 5 km उत्तर → A = (0, 5)।<br>चरण 2: C, B के 12 km पूर्व → C = (12, 0)।<br>चरण 3: A–C दूरी = √(12² + 5²) = √(144 + 25) = √169 = 13 km।<br>अतः उत्तर = <b>13 km</b><br><b>शॉर्टकट:</b> 5-12-13 पाइथागोरस त्रिक।"},
    {"q":"A, B के 5 km उत्तर में है और C, B के 12 km पूर्व में है। C, A से किस दिशा में है?","o":["उत्तर-पूर्व","दक्षिण-पूर्व","दक्षिण-पश्चिम","उत्तर-पश्चिम"],"a":1,"e":"<b>हल:</b><br>निर्देशांक: B = (0, 0), A = (0, 5), C = (12, 0)।<br>चरण 1: A से C तक जाने में x: 0 → 12 (पूर्व की ओर), y: 5 → 0 (दक्षिण की ओर)।<br>चरण 2: पूर्व + दक्षिण = दक्षिण-पूर्व।<br>अतः C, A से = <b>दक्षिण-पूर्व</b><br><b>ध्यान दें:</b> \"C, A से\" पूछा है — A को संदर्भ मानें; उलटा (A, C से) उत्तर-पश्चिम होता।"},
    {"q":"एक लड़का 8 m उत्तर और फिर 15 m पश्चिम चलता है। प्रारंभ से उसकी न्यूनतम दूरी कितनी है?","o":["17 m","23 m","7 m","19 m"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: उत्तर 8 m → (0, 8)।<br>चरण 2: पश्चिम 15 m → (−15, 8)।<br>चरण 3: दूरी = √(15² + 8²) = √(225 + 64) = √289 = 17 m।<br>अतः उत्तर = <b>17 m</b><br><b>शॉर्टकट:</b> 8-15-17 पाइथागोरस त्रिक।"},
    {"q":"एक व्यक्ति 20 m उत्तर, दाएँ मुड़कर 15 m, फिर दाएँ मुड़कर 40 m और फिर दाएँ मुड़कर 15 m चलता है। वह प्रारंभ से कहाँ है?","o":["20 m दक्षिण","20 m उत्तर","40 m दक्षिण","60 m दक्षिण"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख उत्तर, 20 m → (0, 20)।<br>चरण 2: दाएँ → मुख पूर्व, 15 m → (15, 20)।<br>चरण 3: दाएँ → मुख दक्षिण, 40 m → (15, −20)।<br>चरण 4: दाएँ → मुख पश्चिम, 15 m → (0, −20)।<br>चरण 5: अंतिम (0, −20) → 20 m दक्षिण।<br>अतः उत्तर = <b>20 m दक्षिण</b>"},
    {"q":"यदि दक्षिण-पूर्व को उत्तर और उत्तर-पूर्व को पश्चिम कहा जाए, तो पश्चिम को क्या कहा जाएगा?","o":["उत्तर-पूर्व","दक्षिण-पूर्व","दक्षिण-पश्चिम","उत्तर-पश्चिम"],"a":1,"e":"<b>हल:</b><br>नियम: दक्षिणावर्त (घड़ी की दिशा) = उ → उपू → पू → दपू → द → दप → प → उप → उ (हर कदम 45°)।<br>चरण 1: दक्षिण-पूर्व → उत्तर: दक्षिण-पूर्व से उत्तर तक वामावर्त 135° (दपू → पू → उपू → उ)।<br>चरण 2: जाँच — उत्तर-पूर्व → पश्चिम: उपू से 135° वामावर्त = उ → उप → प ✓ (नियम एक ही है)।<br>चरण 3: पश्चिम को 135° वामावर्त घुमाएँ: प → दप (45°) → द (90°) → दपू (135°)।<br>अतः पश्चिम को कहेंगे = <b>दक्षिण-पूर्व</b>"},
    {"q":"मीना घर से 2 km पूर्व, फिर 3 km उत्तर, फिर 2 km पश्चिम जाती है। वह घर से कितनी दूर है?","o":["7 km","5 km","3 km","2 km"],"a":2,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: पूर्व 2 km → (2, 0)।<br>चरण 2: उत्तर 3 km → (2, 3)।<br>चरण 3: पश्चिम 2 km → (0, 3)।<br>चरण 4: घर से दूरी = 3 km (ठीक उत्तर में)।<br>अतः उत्तर = <b>3 km</b><br><b>ध्यान दें:</b> 7 km कुल चली गई दूरी है।"},
    {"q":"एक व्यक्ति 4 km दक्षिण चलकर बाएँ मुड़ता है और 3 km चलता है। वह प्रारंभ से कहाँ है?","o":["5 km दक्षिण-पश्चिम","7 km दक्षिण-पूर्व","1 km पूर्व","5 km दक्षिण-पूर्व"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख दक्षिण, 4 km → (0, −4)।<br>चरण 2: बाएँ मुड़ा → मुख पूर्व (दक्षिण मुख का बायाँ = पूर्व), 3 km → (3, −4)।<br>चरण 3: दूरी = √(3² + 4²) = √25 = 5 km।<br>चरण 4: x धनात्मक (पूर्व), y ऋणात्मक (दक्षिण) → दक्षिण-पूर्व।<br>अतः उत्तर = <b>5 km दक्षिण-पूर्व</b><br><b>ध्यान दें:</b> बाएँ को पश्चिम मान लेने से \"दक्षिण-पश्चिम\" की गलती होती है।"},
    {"q":"एक व्यक्ति 3 km पूर्व, दाएँ मुड़कर 4 km, फिर दाएँ मुड़कर 3 km और फिर बाएँ मुड़कर 2 km चलता है। वह प्रारंभ से कहाँ है?","o":["4 km दक्षिण","6 km उत्तर","6 km दक्षिण","12 km दक्षिण"],"a":2,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख पूर्व, 3 km → (3, 0)।<br>चरण 2: दाएँ → मुख दक्षिण, 4 km → (3, −4)।<br>चरण 3: दाएँ → मुख पश्चिम, 3 km → (0, −4)।<br>चरण 4: बाएँ → मुख दक्षिण (पश्चिम मुख का बायाँ = दक्षिण), 2 km → (0, −6)।<br>चरण 5: अंतिम (0, −6) → 6 km दक्षिण।<br>अतः उत्तर = <b>6 km दक्षिण</b>"},
    {"q":"मैं घर से 1 km उत्तर, फिर 1 km पूर्व, फिर 1 km दक्षिण और फिर 1 km पूर्व चलता हूँ। घर से मेरी स्थिति क्या है?","o":["2 km पूर्व","4 km पूर्व","2 km पश्चिम","1 km उत्तर-पूर्व"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: उत्तर 1 km → (0, 1)।<br>चरण 2: पूर्व 1 km → (1, 1)।<br>चरण 3: दक्षिण 1 km → (1, 0)।<br>चरण 4: पूर्व 1 km → (2, 0)।<br>चरण 5: अंतिम (2, 0) → 2 km पूर्व।<br>अतः उत्तर = <b>2 km पूर्व</b>"},
    {"q":"पूर्व की ओर मुँह किए एक व्यक्ति क्रम से बाएँ, बाएँ और फिर दाएँ मुड़ता है। अब उसका मुख किस ओर है?","o":["दक्षिण","पूर्व","पश्चिम","उत्तर"],"a":3,"e":"<b>हल:</b><br>चरण 1: प्रारंभिक मुख = पूर्व।<br>चरण 2: बाएँ → उत्तर।<br>चरण 3: बाएँ → पश्चिम।<br>चरण 4: दाएँ → उत्तर।<br>अतः उत्तर = <b>उत्तर</b><br><b>शॉर्टकट:</b> 2 बाएँ + 1 दायाँ = कुल 1 बायाँ; पूर्व का बायाँ = उत्तर।"},
    {"q":"दक्षिण-पश्चिम की ओर मुँह किए व्यक्ति 270° वामावर्त घूमता है। अब उसका मुख किस ओर है?","o":["दक्षिण-पूर्व","उत्तर-पश्चिम","उत्तर-पूर्व","दक्षिण"],"a":1,"e":"<b>हल:</b><br>नियम: वामावर्त क्रम = उ → उप → प → दप → द → दपू → पू → उपू → उ (हर कदम 45°)।<br>चरण 1: 270° वामावर्त = 360° − 90° = 90° दक्षिणावर्त के बराबर।<br>चरण 2: दक्षिण-पश्चिम से 90° दक्षिणावर्त: दप → प (45°) → उप (90°)।<br>अतः उत्तर = <b>उत्तर-पश्चिम</b>"},
    {"q":"एक कार 24 km उत्तर और फिर 7 km पूर्व जाती है। प्रारंभ से उसकी सीधी दूरी कितनी है?","o":["31 km","25 km","17 km","27 km"],"a":1,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: उत्तर 24 km → (0, 24)।<br>चरण 2: पूर्व 7 km → (7, 24)।<br>चरण 3: सीधी दूरी = √(7² + 24²) = √(49 + 576) = √625 = 25 km।<br>अतः उत्तर = <b>25 km</b><br><b>शॉर्टकट:</b> 7-24-25 पाइथागोरस त्रिक।"},
    {"q":"दो व्यक्ति एक ही बिंदु से चलते हैं — एक 9 km पूर्व और दूसरा 12 km दक्षिण। उनके बीच की दूरी कितनी है?","o":["21 km","3 km","18 km","15 km"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: साझा बिंदु = (0, 0)।<br>चरण 1: पहला व्यक्ति 9 km पूर्व → (9, 0)।<br>चरण 2: दूसरा 12 km दक्षिण → (0, −12)।<br>चरण 3: दोनों के बीच समकोण बनता है → दूरी = √(9² + 12²) = √(81 + 144) = √225 = 15 km।<br>अतः उत्तर = <b>15 km</b><br><b>शॉर्टकट:</b> 9-12-15 (3-4-5 का तिगुना)।"},
    {"q":"दो व्यक्ति एक ही बिंदु से विपरीत दिशाओं में क्रमशः 5 km और 7 km चलते हैं। उनके बीच की दूरी कितनी है?","o":["12 km","2 km","35 km","7 km"],"a":0,"e":"<b>हल:</b><br>चरण 1: विपरीत दिशाएँ = एक सीधी रेखा पर, उलटी ओर।<br>चरण 2: एक बिंदु से 5 km एक ओर, दूसरा 7 km दूसरी ओर।<br>चरण 3: बीच की दूरी = 5 + 7 = 12 km।<br>अतः उत्तर = <b>12 km</b><br><b>ध्यान दें:</b> एक ही दिशा में चलते तो दूरी 7 − 5 = 2 km होती।"},
    {"q":"स्कूल, घर से उत्तर-पूर्व दिशा में है। घर, स्कूल से किस दिशा में है?","o":["उत्तर-पूर्व","दक्षिण-पूर्व","दक्षिण-पश्चिम","उत्तर-पश्चिम"],"a":2,"e":"<b>हल:</b><br>चरण 1: स्कूल, घर से उत्तर-पूर्व में है।<br>चरण 2: उलटी दिशा पूछी है — स्कूल से घर।<br>चरण 3: उत्तर-पूर्व का विपरीत = दक्षिण-पश्चिम (उ ↔ द, पू ↔ प)।<br>अतः उत्तर = <b>दक्षिण-पश्चिम</b>"},
    {"q":"Q, P के 10 m पश्चिम में है और R, Q के 10 m उत्तर में है। P, R से किस दिशा में है?","o":["उत्तर-पूर्व","दक्षिण-पश्चिम","उत्तर-पश्चिम","दक्षिण-पूर्व"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: P = (0, 0)।<br>चरण 1: Q, P के 10 m पश्चिम → Q = (−10, 0)।<br>चरण 2: R, Q के 10 m उत्तर → R = (−10, 10)।<br>चरण 3: R से P तक: x −10 → 0 (पूर्व), y 10 → 0 (दक्षिण)।<br>चरण 4: पूर्व + दक्षिण = दक्षिण-पूर्व।<br>अतः P, R से = <b>दक्षिण-पूर्व</b>"},
    {"q":"सुबह 7 बजे किसी पेड़ की छाया किस दिशा में पड़ेगी?","o":["पूर्व","उत्तर","पश्चिम","दक्षिण"],"a":2,"e":"<b>हल:</b><br>चरण 1: सुबह 7 बजे सूर्य पूर्व में होता है।<br>चरण 2: छाया सूर्य की विपरीत दिशा में बनती है।<br>चरण 3: पूर्व का विपरीत = पश्चिम।<br>अतः उत्तर = <b>पश्चिम</b>"},
    {"q":"एक पंक्ति में राम बाएँ से 12वाँ और दाएँ से 18वाँ है। पंक्ति में कुल कितने व्यक्ति हैं?","o":["30","29","28","31"],"a":1,"e":"<b>हल:</b><br>सूत्र: कुल = बाएँ से स्थान + दाएँ से स्थान − 1<br>चरण 1: कुल = 12 + 18 − 1 = 29।<br>(राम दोनों गिनतियों में शामिल है, इसलिए एक बार घटाया।)<br>अतः उत्तर = <b>29</b><br><b>ध्यान दें:</b> 1 न घटाने पर 30 (गलत विकल्प) आता है।"},
    {"q":"कक्षा में मोहन का स्थान ऊपर से 15वाँ और नीचे से 25वाँ है। कक्षा में कुल कितने छात्र हैं?","o":["39","40","41","38"],"a":0,"e":"<b>हल:</b><br>सूत्र: कुल = ऊपर से रैंक + नीचे से रैंक − 1<br>चरण 1: कुल = 15 + 25 − 1 = 39।<br>अतः उत्तर = <b>39</b>"},
    {"q":"40 बच्चों की पंक्ति में सीता बाएँ से 16वीं है। दाएँ से उसका स्थान क्या है?","o":["25वाँ","24वाँ","26वाँ","23वाँ"],"a":0,"e":"<b>हल:</b><br>सूत्र: दाएँ से स्थान = कुल − बाएँ से स्थान + 1<br>चरण 1: = 40 − 16 + 1 = 25।<br>जाँच: 16 + 25 − 1 = 40 ✓<br>अतः उत्तर = <b>25वाँ</b>"},
    {"q":"एक पंक्ति में A बाएँ से 10वाँ और B दाएँ से 10वाँ है। दोनों के स्थान आपस में बदलने पर A बाएँ से 15वाँ हो जाता है। पंक्ति में कुल कितने व्यक्ति हैं?","o":["25","24","23","26"],"a":1,"e":"<b>हल:</b><br>चरण 1: स्थान बदलने पर A, B की पुरानी जगह पर पहुँचता है।<br>चरण 2: B की पुरानी जगह = दाएँ से 10वीं; अब A वहाँ बाएँ से 15वाँ है।<br>चरण 3: अतः उसी एक जगह का बाएँ से स्थान 15 और दाएँ से 10।<br>चरण 4: कुल = 15 + 10 − 1 = 24।<br>अतः उत्तर = <b>24</b><br><b>ध्यान दें:</b> A का पुराना स्थान (बाएँ से 10वाँ) यहाँ अनावश्यक है।"},
    {"q":"30 व्यक्तियों की पंक्ति में A बाएँ से 7वाँ और B दाएँ से 12वाँ है। A और B के बीच कितने व्यक्ति हैं?","o":["10","12","11","9"],"a":2,"e":"<b>हल:</b><br>चरण 1: A बाएँ से 7वाँ।<br>चरण 2: B दाएँ से 12वाँ → बाएँ से = 30 − 12 + 1 = 19वाँ।<br>चरण 3: बीच के व्यक्ति = 19 − 7 − 1 = 11।<br>अतः उत्तर = <b>11</b><br><b>शॉर्टकट:</b> बीच के व्यक्ति = कुल − (7 + 12) = 30 − 19 = 11 (जब दोनों ओवरलैप न करें)।"},
    {"q":"50 छात्रों में राजू का स्थान ऊपर से 21वाँ है। नीचे से उसका स्थान क्या है?","o":["29वाँ","31वाँ","28वाँ","30वाँ"],"a":3,"e":"<b>हल:</b><br>सूत्र: नीचे से रैंक = कुल − ऊपर से रैंक + 1<br>चरण 1: = 50 − 21 + 1 = 30।<br>अतः उत्तर = <b>30वाँ</b><br><b>ध्यान दें:</b> +1 भूलने पर 29 (गलत विकल्प) आता है।"},
    {"q":"A, B से लंबा है; B, C से लंबा है; D, A से लंबा है; E, C से छोटा है। सबसे लंबा कौन है?","o":["A","B","D","E"],"a":2,"e":"<b>हल:</b><br>चरण 1: A > B, B > C → A > B > C।<br>चरण 2: D > A → D > A > B > C।<br>चरण 3: E < C → D > A > B > C > E।<br>अतः सबसे लंबा = <b>D</b>"},
    {"q":"A, B से लंबा है; B, C से लंबा है; D, A से लंबा है; E, C से छोटा है। लंबाई के क्रम में बीच (तीसरे स्थान) पर कौन है?","o":["B","A","C","D"],"a":0,"e":"<b>हल:</b><br>चरण 1: A > B > C (पहले दो कथन)।<br>चरण 2: D > A → D > A > B > C।<br>चरण 3: E < C → पूरा क्रम: D > A > B > C > E।<br>चरण 4: तीसरा (बीच का) स्थान = B।<br>अतः उत्तर = <b>B</b>"},
    {"q":"P, Q से भारी है पर R से हल्का है। S, R से भारी है। सबसे भारी कौन है?","o":["R","P","Q","S"],"a":3,"e":"<b>हल:</b><br>चरण 1: P > Q और P < R → R > P > Q।<br>चरण 2: S > R → S > R > P > Q।<br>अतः सबसे भारी = <b>S</b>"},
    {"q":"25 लड़कों की पंक्ति में राहुल दोनों छोरों से समान स्थान पर है। उसका स्थान क्या है?","o":["12वाँ","13वाँ","14वाँ","11वाँ"],"a":1,"e":"<b>हल:</b><br>चरण 1: दोनों छोरों से समान स्थान x हो तो कुल = x + x − 1 = 2x − 1।<br>चरण 2: 2x − 1 = 25 → 2x = 26 → x = 13।<br>अतः उत्तर = <b>13वाँ</b><br><b>शॉर्टकट:</b> विषम कुल n में ठीक बीच वाला = (n + 1)/2 = 26/2 = 13।"},
    {"q":"एक कतार में X आगे से 9वाँ और Y पीछे से 9वाँ है। X, Y से आगे है और दोनों के बीच 4 व्यक्ति हैं। कतार में कुल कितने व्यक्ति हैं?","o":["21","22","23","13"],"a":1,"e":"<b>हल:</b><br>चरण 1: X आगे से 9वाँ।<br>चरण 2: X, Y से आगे और बीच में 4 व्यक्ति → Y आगे से 9 + 4 + 1 = 14वाँ।<br>चरण 3: Y पीछे से 9वाँ → कुल = 14 + 9 − 1 = 22।<br>क्रम: [8 व्यक्ति] X [4 व्यक्ति] Y [8 व्यक्ति] → 8 + 1 + 4 + 1 + 8 = 22 ✓<br>अतः उत्तर = <b>22</b>"},
    {"q":"कक्षा में रीता का स्थान ऊपर से 8वाँ और नीचे से 37वाँ है। कक्षा में कितनी छात्राएँ हैं?","o":["45","43","46","44"],"a":3,"e":"<b>हल:</b><br>सूत्र: कुल = ऊपर से + नीचे से − 1<br>चरण 1: = 8 + 37 − 1 = 44।<br>अतः उत्तर = <b>44</b><br><b>ध्यान दें:</b> 1 न घटाने पर 45 आता है।"},
    {"q":"एक पंक्ति में A बाएँ से 18वाँ और B दाएँ से 22वाँ है। A, B के बाईं ओर है और दोनों के बीच 5 व्यक्ति हैं। पंक्ति में कुल कितने व्यक्ति हैं?","o":["45","46","44","35"],"a":0,"e":"<b>हल:</b><br>चरण 1: A बाएँ से 18वाँ।<br>चरण 2: A, B के बाईं ओर और बीच में 5 → B बाएँ से 18 + 5 + 1 = 24वाँ।<br>चरण 3: B दाएँ से 22वाँ → कुल = 24 + 22 − 1 = 45।<br>क्रम: [17] A [5] B [21] → 17 + 1 + 5 + 1 + 21 = 45 ✓<br>अतः उत्तर = <b>45</b>"},
    {"q":"मोहन, सोहन से बड़ा है; रोहन, मोहन से बड़ा है; सोहन, गोपाल से बड़ा है। सबसे छोटा कौन है?","o":["सोहन","मोहन","गोपाल","रोहन"],"a":2,"e":"<b>हल:</b><br>चरण 1: रोहन > मोहन (रोहन, मोहन से बड़ा)।<br>चरण 2: मोहन > सोहन → रोहन > मोहन > सोहन।<br>चरण 3: सोहन > गोपाल → रोहन > मोहन > सोहन > गोपाल।<br>अतः सबसे छोटा = <b>गोपाल</b>"},
    {"q":"A, B, C, D, E एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं। C, A और E के बीच (ठीक बगल में) है। B, E के ठीक दाईं ओर है। D, A के ठीक बाईं ओर है। बीच में कौन बैठा है?","o":["A","E","D","C"],"a":3,"e":"<b>हल:</b><br>उत्तर की ओर मुख → बायाँ = पश्चिम, दायाँ = पूर्व; पंक्ति को बाएँ से दाएँ लिखें।<br>चरण 1: D, A के ठीक बाएँ → D A<br>चरण 2: C, A और E के बीच (ठीक बगल में) → D A C E<br>चरण 3: B, E के ठीक दाएँ → D A C E B<br>अंतिम क्रम (बाएँ → दाएँ): <b>D, A, C, E, B</b><br>चरण 4: 5 में बीच = तीसरा = C।<br>अतः उत्तर = <b>C</b>"},
    {"q":"A, B, C, D, E एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं। C, A और E के बीच (ठीक बगल में) है। B, E के ठीक दाईं ओर है। D, A के ठीक बाईं ओर है। दाएँ छोर पर कौन है?","o":["D","E","B","A"],"a":2,"e":"<b>हल:</b><br>उत्तर की ओर मुख → क्रम बाएँ से दाएँ लिखें।<br>चरण 1: D, A के ठीक बाएँ → D A<br>चरण 2: C, A और E के बीच → D A C E<br>चरण 3: B, E के ठीक दाएँ → D A C E B<br>अंतिम क्रम: <b>D, A, C, E, B</b><br>चरण 4: दाएँ छोर = B।<br>अतः उत्तर = <b>B</b>"},
    {"q":"छह मित्र A, B, C, D, E, F एक वृत्त में केंद्र की ओर मुँह करके बैठे हैं। B, A के ठीक बाएँ है; C, B के ठीक बाएँ है; D, A के ठीक सामने है; E, D और F के बीच है। F के ठीक बाएँ कौन है?","o":["E","A","B","D"],"a":1,"e":"<b>हल:</b><br>केंद्र की ओर मुख होने पर किसी का \"बायाँ\" = वृत्त में दक्षिणावर्त अगला स्थान। स्थानों को 1 से 6 तक दक्षिणावर्त गिनें।<br>चरण 1: A = 1।<br>चरण 2: B, A के ठीक बाएँ → B = 2; C, B के ठीक बाएँ → C = 3।<br>चरण 3: D, A के ठीक सामने (6 में 3 स्थान दूर) → D = 4।<br>चरण 4: बचे स्थान 5, 6; E, D और F के बीच → E = 5, F = 6।<br>दक्षिणावर्त क्रम: <b>A, B, C, D, E, F</b> (फिर A)<br>चरण 5: F (6) का ठीक बायाँ = अगला स्थान 1 = A।<br>अतः उत्तर = <b>A</b>"},
    {"q":"छह मित्र A, B, C, D, E, F एक वृत्त में केंद्र की ओर मुँह करके बैठे हैं। B, A के ठीक बाएँ है; C, B के ठीक बाएँ है; D, A के ठीक सामने है; E, D और F के बीच है। C के ठीक सामने कौन है?","o":["F","E","A","B"],"a":0,"e":"<b>हल:</b><br>स्थान 1–6 दक्षिणावर्त (केंद्र की ओर मुख: बायाँ = दक्षिणावर्त अगला)।<br>चरण 1: A = 1; B = 2 (A के बाएँ); C = 3 (B के बाएँ)।<br>चरण 2: D, A के सामने → 4।<br>चरण 3: E, D और F के बीच → E = 5, F = 6।<br>क्रम: A(1), B(2), C(3), D(4), E(5), F(6)<br>चरण 4: सामने = 3 स्थान दूर → C (3) के सामने = 6 = F।<br>अतः उत्तर = <b>F</b>"},
    {"q":"P, Q, R, S एक वर्गाकार मेज़ पर केंद्र की ओर मुँह करके बैठे हैं। P के सामने R है और Q, P के ठीक बाएँ है। S, P के किस ओर है?","o":["दाएँ","बाएँ","सामने","पीछे"],"a":0,"e":"<b>हल:</b><br>चरण 1: P के सामने R।<br>चरण 2: Q, P के ठीक बाएँ → P की एक बगल वाली सीट Q।<br>चरण 3: बची एक सीट — P की दूसरी बगल, यानी P का दायाँ — पर S।<br>व्यवस्था (P से घूमते हुए): P → बाएँ Q → सामने R → दाएँ S<br>अतः S, P के = <b>दाएँ</b>"},
    {"q":"पाँच लड़के दक्षिण की ओर मुँह करके एक पंक्ति में खड़े हैं। M, N के ठीक बाएँ है; O, N के ठीक दाएँ है; P, M के ठीक बाएँ है; Q, O के ठीक दाएँ है। बीच में कौन है?","o":["M","N","O","P"],"a":1,"e":"<b>हल:</b><br>चरण 1: सभी बाएँ/दाएँ लड़कों के अपने मुख (दक्षिण) के अनुसार हैं; पंक्ति को उनके बाएँ से दाएँ लिखें।<br>चरण 2: M, N के ठीक बाएँ → M N<br>चरण 3: O, N के ठीक दाएँ → M N O<br>चरण 4: P, M के ठीक बाएँ → P M N O<br>चरण 5: Q, O के ठीक दाएँ → P M N O Q<br>अंतिम क्रम: <b>P, M, N, O, Q</b><br>चरण 6: बीच (तीसरा) = N।<br>अतः उत्तर = <b>N</b>"},
    {"q":"उत्तर की ओर मुँह किए 7 लोगों की पंक्ति में X बाएँ छोर से तीसरा और Y दाएँ छोर से दूसरा है। X और Y के बीच कितने लोग हैं?","o":["3","1","2","4"],"a":2,"e":"<b>हल:</b><br>चरण 1: X बाएँ से तीसरा → स्थान 3।<br>चरण 2: Y दाएँ से दूसरा → बाएँ से 7 − 2 + 1 = 6।<br>चरण 3: बीच के लोग = 6 − 3 − 1 = 2 (स्थान 4 और 5)।<br>क्रम: _ _ X _ _ Y _<br>अतः उत्तर = <b>2</b>"},
    {"q":"A, B, C, D, E एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं। E, C के ठीक दाएँ है; B, E के ठीक दाएँ है; D दाएँ छोर पर है; A, D के ठीक बाएँ नहीं है। बाएँ से दूसरे स्थान पर कौन है?","o":["A","E","B","C"],"a":3,"e":"<b>हल:</b><br>उत्तर की ओर मुख → स्थान 1 (बायाँ) से 5 (दायाँ)।<br>चरण 1: D दाएँ छोर पर → D = 5।<br>चरण 2: E, C के ठीक दाएँ और B, E के ठीक दाएँ → C E B लगातार।<br>चरण 3: संभावना (i): C E B = 1, 2, 3 → A = 4 → A, D के ठीक बाएँ — यह मना है ✗।<br>चरण 4: संभावना (ii): C E B = 2, 3, 4 → A = 1 ✓।<br>अंतिम क्रम: <b>A, C, E, B, D</b><br>चरण 5: बाएँ से दूसरा = C।<br>अतः उत्तर = <b>C</b>"},
    {"q":"एक पंक्ति में K बाएँ से 13वाँ और दाएँ से भी 13वाँ है। पंक्ति में कुल कितने व्यक्ति हैं?","o":["26","24","25","27"],"a":2,"e":"<b>हल:</b><br>सूत्र: कुल = बाएँ से + दाएँ से − 1<br>चरण 1: = 13 + 13 − 1 = 25।<br>अतः उत्तर = <b>25</b><br><b>ध्यान दें:</b> 26 चुनना सामान्य गलती है — K दोनों गिनतियों में है।"},
    {"q":"31 छात्रों की परीक्षा में अमन ऊपर से 9वें स्थान पर है। उससे नीचे के 3 छात्रों का परिणाम रद्द हो जाए, तो नीचे से अमन का स्थान क्या होगा?","o":["20वाँ","23वाँ","21वाँ","19वाँ"],"a":0,"e":"<b>हल:</b><br>चरण 1: पहले नीचे से अमन का स्थान = 31 − 9 + 1 = 23वाँ (उससे नीचे 22 छात्र)।<br>चरण 2: उससे नीचे के 3 छात्रों का परिणाम रद्द → नीचे बचे 22 − 3 = 19 छात्र।<br>चरण 3: नीचे से नया स्थान = 19 + 1 = 20वाँ।<br>अतः उत्तर = <b>20वाँ</b><br><b>ध्यान दें:</b> 23वाँ पुराना स्थान है; रद्द होने वाले छात्र उससे नीचे हैं, इसलिए नीचे से उसका स्थान 3 घटता है।"},
    {"q":"एक कतार में 5 लड़कियाँ हैं। सीमा, रीना के आगे है पर गीता के पीछे। मीना सबसे आगे है और टीना सबसे पीछे। आगे से तीसरे स्थान पर कौन है?","o":["गीता","रीना","मीना","सीमा"],"a":3,"e":"<b>हल:</b><br>चरण 1: मीना सबसे आगे (1), टीना सबसे पीछे (5)।<br>चरण 2: सीमा, रीना के आगे पर गीता के पीछे → गीता … सीमा … रीना।<br>चरण 3: बचे स्थान 2, 3, 4 → गीता = 2, सीमा = 3, रीना = 4।<br>अंतिम क्रम (आगे → पीछे): <b>मीना, गीता, सीमा, रीना, टीना</b><br>अतः तीसरे स्थान पर = <b>सीमा</b>"},
    {"q":"पूर्व की ओर मुँह किए एक व्यक्ति पीछे मुड़ता है, फिर बाएँ मुड़ता है। अब उसका मुख किस ओर है?","o":["उत्तर","दक्षिण","पूर्व","पश्चिम"],"a":1,"e":"<b>हल:</b><br>चरण 1: प्रारंभिक मुख = पूर्व।<br>चरण 2: पीछे मुड़ा (180°) → पश्चिम।<br>चरण 3: बाएँ मुड़ा → पश्चिम मुख का बायाँ = दक्षिण।<br>अतः उत्तर = <b>दक्षिण</b>"},
    {"q":"एक व्यक्ति 12 km पश्चिम चलता है, फिर बाएँ मुड़कर 5 km चलता है। प्रारंभ से उसकी दूरी कितनी है?","o":["17 km","13 km","7 km","15 km"],"a":1,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख पश्चिम, 12 km → (−12, 0)।<br>चरण 2: बाएँ मुड़ा → मुख दक्षिण (पश्चिम मुख का बायाँ = दक्षिण), 5 km → (−12, −5)।<br>चरण 3: दूरी = √(12² + 5²) = √(144 + 25) = √169 = 13 km (दिशा: दक्षिण-पश्चिम)।<br>अतः उत्तर = <b>13 km</b>"},
    {"q":"एक व्यक्ति 15 m पश्चिम चलता है, फिर दाएँ मुड़कर 8 m, फिर दाएँ मुड़कर 15 m और अंत में बाएँ मुड़कर 4 m चलता है। अब वह प्रारंभिक बिंदु से कहाँ है?","o":["8 m पूर्व","12 m दक्षिण","12 m उत्तर","4 m उत्तर"],"a":2,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख पश्चिम, 15 m → (−15, 0)।<br>चरण 2: दाएँ → मुख उत्तर, 8 m → (−15, 8)।<br>चरण 3: दाएँ → मुख पूर्व, 15 m → (0, 8)।<br>चरण 4: बाएँ → मुख उत्तर (पूर्व मुख का बायाँ = उत्तर), 4 m → (0, 12)।<br>चरण 5: अंतिम (0, 12) → 12 m उत्तर।<br>अतः उत्तर = <b>12 m उत्तर</b>"},
    {"q":"नेहा अपने घर से 3 km उत्तर, फिर 4 km पूर्व, फिर 6 km दक्षिण और फिर 4 km पश्चिम जाती है। अब वह घर से कहाँ है?","o":["3 km दक्षिण","9 km दक्षिण","3 km उत्तर","5 km दक्षिण-पूर्व"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: उत्तर 3 km → (0, 3)।<br>चरण 2: पूर्व 4 km → (4, 3)।<br>चरण 3: दक्षिण 6 km → (4, −3)।<br>चरण 4: पश्चिम 4 km → (0, −3)।<br>चरण 5: अंतिम (0, −3) → 3 km दक्षिण।<br>अतः उत्तर = <b>3 km दक्षिण</b>"},
    {"q":"एक व्यक्ति 5 km पूर्व, 4 km उत्तर, 7 km पूर्व और फिर 1 km उत्तर चलता है। प्रारंभिक बिंदु से उसकी सीधी दूरी कितनी है?","o":["15 km","17 km","12 km","13 km"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: पूर्व 5 → (5, 0); उत्तर 4 → (5, 4)।<br>चरण 2: पूर्व 7 → (12, 4); उत्तर 1 → (12, 5)।<br>चरण 3: कुल पूर्व = 12, कुल उत्तर = 5।<br>चरण 4: सीधी दूरी = √(12² + 5²) = √169 = 13 km।<br>अतः उत्तर = <b>13 km</b><br><b>शॉर्टकट:</b> एक दिशा के सभी कदम जोड़ लें (5 + 7, 4 + 1), फिर पाइथागोरस।"},
    {"q":"शाम के समय रवि और अशोक आमने-सामने खड़े होकर बात कर रहे हैं। रवि की छाया ठीक उसकी दाईं ओर पड़ रही है। अशोक का मुख किस दिशा में है?","o":["दक्षिण","पूर्व","पश्चिम","उत्तर"],"a":0,"e":"<b>हल:</b><br>चरण 1: शाम को सूर्य पश्चिम में → छाया पूर्व की ओर।<br>चरण 2: रवि की छाया दाईं ओर → रवि का दायाँ = पूर्व → रवि का मुख उत्तर।<br>चरण 3: अशोक, रवि के आमने-सामने → अशोक का मुख रवि के विपरीत = दक्षिण।<br>अतः उत्तर = <b>दक्षिण</b><br><b>ध्यान दें:</b> उत्तर रवि का मुख है; प्रश्न अशोक का पूछ रहा है।"},
    {"q":"सूर्यास्त के समय एक व्यक्ति सूर्य की ओर पीठ करके खड़ा है। फिर वह बाएँ मुड़ता है। अब उसका मुख किस दिशा में है?","o":["पश्चिम","पूर्व","उत्तर","दक्षिण"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूर्यास्त पर सूर्य पश्चिम में।<br>चरण 2: सूर्य की ओर पीठ → मुख पूर्व।<br>चरण 3: बाएँ मुड़ा → पूर्व मुख का बायाँ = उत्तर।<br>अतः उत्तर = <b>उत्तर</b>"},
    {"q":"यदि उत्तर को पश्चिम, पश्चिम को दक्षिण कहा जाए और इसी प्रकार सभी दिशाएँ बदल दी जाएँ, तो पूर्व को क्या कहा जाएगा?","o":["पश्चिम","पूर्व","दक्षिण","उत्तर"],"a":3,"e":"<b>हल:</b><br>चरण 1: उत्तर → पश्चिम: 90° वामावर्त घुमाव।<br>चरण 2: पश्चिम → दक्षिण: फिर 90° वामावर्त ✓ (नियम एक ही)।<br>चरण 3: पूर्व को 90° वामावर्त घुमाएँ → उत्तर।<br>अतः पूर्व को कहेंगे = <b>उत्तर</b>"},
    {"q":"एक घड़ी 9:00 बजा रही है और उसकी मिनट की सुई पूर्व दिशा की ओर है। घंटे की सुई किस दिशा की ओर होगी?","o":["पूर्व","उत्तर","दक्षिण","पश्चिम"],"a":1,"e":"<b>हल:</b><br>चरण 1: 9:00 पर मिनट की सुई 12 पर और घंटे की सुई 9 पर।<br>चरण 2: 12 → पूर्व दिशा में (दिया है)।<br>चरण 3: घड़ी में 9, 12 से 90° वामावर्त है।<br>चरण 4: पूर्व से 90° वामावर्त = उत्तर।<br>अतः घंटे की सुई = <b>उत्तर</b><br><b>ध्यान दें:</b> सामान्य घड़ी में 9 पश्चिम होता है, पर यहाँ घड़ी 90° घूमी हुई है (12 पूर्व में)।"},
    {"q":"P, Q से 4 m पूर्व में है। R, P से 3 m दक्षिण में है। S, R से 4 m पश्चिम में है। S, Q के सापेक्ष कहाँ है?","o":["3 m दक्षिण","3 m उत्तर","4 m पश्चिम","5 m दक्षिण-पूर्व"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: Q = (0, 0)।<br>चरण 1: P, Q से 4 m पूर्व → P = (4, 0)।<br>चरण 2: R, P से 3 m दक्षिण → R = (4, −3)।<br>चरण 3: S, R से 4 m पश्चिम → S = (0, −3)।<br>चरण 4: Q (0, 0) के सापेक्ष S (0, −3) → 3 m दक्षिण।<br>अतः उत्तर = <b>3 m दक्षिण</b>"},
    {"q":"A, B से 6 m उत्तर में है और C, A से 8 m पश्चिम में है। C, B से कितनी दूर और किस दिशा में है?","o":["10 m उत्तर-पूर्व","14 m उत्तर-पश्चिम","10 m उत्तर-पश्चिम","10 m दक्षिण-पश्चिम"],"a":2,"e":"<b>हल:</b><br>निर्देशांक: B = (0, 0)।<br>चरण 1: A, B से 6 m उत्तर → A = (0, 6)।<br>चरण 2: C, A से 8 m पश्चिम → C = (−8, 6)।<br>चरण 3: दूरी B–C = √(8² + 6²) = √100 = 10 m।<br>चरण 4: x ऋणात्मक (पश्चिम), y धनात्मक (उत्तर) → उत्तर-पश्चिम।<br>अतः उत्तर = <b>10 m उत्तर-पश्चिम</b>"},
    {"q":"उत्तर-पश्चिम की ओर मुँह किए एक व्यक्ति 90° दक्षिणावर्त घूमता है और फिर 225° वामावर्त घूमता है। अब उसका मुख किस दिशा में है?","o":["उत्तर","दक्षिण","पूर्व","दक्षिण-पश्चिम"],"a":1,"e":"<b>हल:</b><br>नियम: दक्षिणावर्त (घड़ी की दिशा) = उ → उपू → पू → दपू → द → दप → प → उप → उ (हर कदम 45°)।<br>चरण 1: प्रारंभिक मुख = उत्तर-पश्चिम।<br>चरण 2: 90° दक्षिणावर्त: उप → उ (45°) → उपू (90°) → मुख उत्तर-पूर्व।<br>चरण 3: 225° वामावर्त (= 5 कदम): उपू → उ → उप → प → दप → द → मुख दक्षिण।<br>अतः उत्तर = <b>दक्षिण</b><br><b>शॉर्टकट:</b> कुल = 225° − 90° = 135° वामावर्त; उप से 135° वामावर्त: प → दप → द।"},
    {"q":"एक व्यक्ति 2 m उत्तर चलता है, फिर दाएँ मुड़कर 4 m, फिर दाएँ मुड़कर 6 m, फिर दाएँ मुड़कर 8 m और फिर दाएँ मुड़कर 10 m चलता है। अब वह प्रारंभिक बिंदु से किस दिशा में है?","o":["उत्तर-पूर्व","उत्तर","दक्षिण-पश्चिम","उत्तर-पश्चिम"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: मुख उत्तर, 2 m → (0, 2)।<br>चरण 2: दाएँ → मुख पूर्व, 4 m → (4, 2)।<br>चरण 3: दाएँ → मुख दक्षिण, 6 m → (4, −4)।<br>चरण 4: दाएँ → मुख पश्चिम, 8 m → (−4, −4)।<br>चरण 5: दाएँ → मुख उत्तर, 10 m → (−4, 6)।<br>चरण 6: x = −4 (पश्चिम), y = +6 (उत्तर) → उत्तर-पश्चिम (दूरी = √(16 + 36) = √52 m)।<br>अतः उत्तर = <b>उत्तर-पश्चिम</b>"},
    {"q":"एक व्यक्ति अपने घर से 30 m दक्षिण और फिर 40 m पश्चिम जाता है। घर लौटने के लिए उसे सीधे किस दिशा में कितनी दूरी तय करनी होगी?","o":["70 m उत्तर-पूर्व","50 m उत्तर-पश्चिम","50 m दक्षिण-पश्चिम","50 m उत्तर-पूर्व"],"a":3,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: दक्षिण 30 m → (0, −30)।<br>चरण 2: पश्चिम 40 m → (−40, −30)।<br>चरण 3: घर तक सीधी दूरी = √(40² + 30²) = √2500 = 50 m।<br>चरण 4: घर पहुँचने के लिए x बढ़ाना है (पूर्व) और y बढ़ाना है (उत्तर) → उत्तर-पूर्व।<br>अतः उत्तर = <b>50 m उत्तर-पूर्व</b><br><b>ध्यान दें:</b> व्यक्ति घर से दक्षिण-पश्चिम में है; लौटने की दिशा उसकी विपरीत = उत्तर-पूर्व।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए — A, B से 10 m पूर्व में है और C, B से 10 m उत्तर में है।<br>1. A, C से दक्षिण-पूर्व दिशा में है।<br>2. A और C के बीच की दूरी 20 m है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: B = (0, 0), A = (10, 0) (पूर्व), C = (0, 10) (उत्तर)।<br>कथन 1: C से A तक — x 0 → 10 (पूर्व), y 10 → 0 (दक्षिण) → A, C से दक्षिण-पूर्व में — <b>सही</b>।<br>कथन 2: A–C दूरी = √(10² + 10²) = √200 = 10√2 ≈ 14.14 m, 20 m नहीं — <b>गलत</b>।<br>अतः उत्तर = <b>केवल 1</b><br><b>ध्यान दें:</b> 20 m = 10 + 10 सीधा जोड़ने की गलती से आता है; समकोण में कर्ण निकालें।"},
    {"q":"शाम के समय एक व्यक्ति उत्तर की ओर मुँह करके खड़ा है। उसकी छाया उसकी किस ओर पड़ेगी?","o":["बाईं ओर","दाईं ओर","ठीक पीछे","ठीक सामने"],"a":1,"e":"<b>हल:</b><br>चरण 1: शाम को सूर्य पश्चिम में → छाया पूर्व की ओर।<br>चरण 2: उत्तर की ओर मुख → दायाँ = पूर्व, बायाँ = पश्चिम।<br>चरण 3: छाया (पूर्व) = दाईं ओर।<br>अतः उत्तर = <b>दाईं ओर</b>"},
    {"q":"एक साइकिल सवार 21 km पश्चिम और फिर 20 km उत्तर चलता है। प्रारंभिक बिंदु से उसकी सीधी दूरी कितनी है?","o":["29 km","41 km","31 km","30 km"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: प्रारंभ = (0, 0), पूर्व = +x, उत्तर = +y।<br>चरण 1: पश्चिम 21 km → (−21, 0)।<br>चरण 2: उत्तर 20 km → (−21, 20)।<br>चरण 3: दूरी = √(21² + 20²) = √(441 + 400) = √841 = 29 km।<br>अतः उत्तर = <b>29 km</b><br><b>शॉर्टकट:</b> 20-21-29 पाइथागोरस त्रिक।<br><b>ध्यान दें:</b> 41 km कुल चली गई दूरी है।"},
    {"q":"अभिकथन (A): सुबह के समय उत्तर की ओर मुँह किए व्यक्ति की छाया उसकी बाईं ओर पड़ती है।<br>कारण (R): सुबह सूर्य पूर्व में होता है, अतः छाया पश्चिम की ओर बनती है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"<b>हल:</b><br>कारण (R): सुबह सूर्य पूर्व में → छाया विपरीत दिशा, पश्चिम में — <b>सही</b>।<br>अभिकथन (A): उत्तर मुख वाले का बायाँ = पश्चिम → छाया (पश्चिम) बाईं ओर — <b>सही</b>।<br>A इसीलिए सत्य है क्योंकि छाया पश्चिम में बनती है (R) → R, A की सही व्याख्या।<br>अतः उत्तर = <b>A और R दोनों सही हैं तथा R, A की सही व्याख्या है</b>"},
    {"q":"राहुल का दफ़्तर उसके घर से 3 km पूर्व में है। बाज़ार दफ़्तर से 4 km उत्तर में है और स्कूल बाज़ार से 3 km पश्चिम में है। स्कूल, घर से कहाँ है?","o":["4 km उत्तर","7 km उत्तर","5 km उत्तर-पूर्व","3 km पश्चिम"],"a":0,"e":"<b>हल:</b><br>निर्देशांक: घर = (0, 0)।<br>चरण 1: दफ़्तर, घर से 3 km पूर्व → (3, 0)।<br>चरण 2: बाज़ार, दफ़्तर से 4 km उत्तर → (3, 4)।<br>चरण 3: स्कूल, बाज़ार से 3 km पश्चिम → (0, 4)।<br>चरण 4: घर (0, 0) से स्कूल (0, 4) → 4 km उत्तर।<br>अतः उत्तर = <b>4 km उत्तर</b><br><b>ध्यान दें:</b> 5 km उत्तर-पूर्व घर से बाज़ार की स्थिति है, स्कूल की नहीं।"},
    {"q":"दक्षिण की ओर मुँह किए एक व्यक्ति लगातार तीन बार दाएँ मुड़ता है। अब उसका मुख किस दिशा में है?","o":["पश्चिम","पूर्व","दक्षिण","उत्तर"],"a":1,"e":"<b>हल:</b><br>चरण 1: प्रारंभिक मुख = दक्षिण।<br>चरण 2: पहला दायाँ → पश्चिम।<br>चरण 3: दूसरा दायाँ → उत्तर।<br>चरण 4: तीसरा दायाँ → पूर्व।<br>अतः उत्तर = <b>पूर्व</b><br><b>शॉर्टकट:</b> 3 दाएँ = 1 बायाँ; दक्षिण मुख का बायाँ = पूर्व।"},
    {"q":"35 बच्चों की एक पंक्ति में A बाएँ से 20वाँ और B दाएँ से 22वाँ है। A और B के बीच कितने बच्चे हैं?","o":["4","6","5","7"],"a":2,"e":"<b>हल:</b><br>चरण 1: A बाएँ से 20वाँ।<br>चरण 2: B दाएँ से 22वाँ → बाएँ से = 35 − 22 + 1 = 14वाँ।<br>चरण 3: B (14) बाईं ओर, A (20) दाईं ओर → बीच = 20 − 14 − 1 = 5।<br>अतः उत्तर = <b>5</b><br><b>ध्यान दें:</b> यहाँ दोनों की गिनतियाँ ओवरलैप करती हैं (20 + 22 = 42 > 35), इसलिए \"कुल − दोनों स्थान\" वाला सूत्र नहीं चलेगा।"},
    {"q":"एक कतार में A आगे से 10वाँ और B पीछे से 6ठा है। A और B के बीच ठीक 3 व्यक्ति हैं। कतार में कम-से-कम कितने व्यक्ति हैं?","o":["12","19","11","18"],"a":2,"e":"<b>हल:</b><br>चरण 1: A आगे से 10वाँ; B पीछे से 6ठा; बीच में 3 व्यक्ति।<br>चरण 2: स्थिति (i) — B, A के पीछे: B आगे से 10 + 3 + 1 = 14वाँ → कुल = 14 + 6 − 1 = 19।<br>चरण 3: स्थिति (ii) — B, A के आगे: B आगे से 10 − 3 − 1 = 6ठा → कुल = 6 + 6 − 1 = 11।<br>जाँच (ii): 11 की कतार में B = 6, A = 10; बीच में 7, 8, 9 = 3 व्यक्ति ✓; A पीछे से 2रा, B पीछे से 6ठा ✓।<br>चरण 4: कम-से-कम = 11।<br>अतः उत्तर = <b>11</b><br><b>ध्यान दें:</b> 19 अधिकतम है; \"कम-से-कम\" पूछा है।"},
    {"q":"एक पंक्ति में A बाएँ से 12वाँ और B दाएँ से 15वाँ है। दोनों अपने स्थान आपस में बदल लेते हैं, तो A बाएँ से 20वाँ हो जाता है। अब B दाएँ से किस स्थान पर है?","o":["24वाँ","22वाँ","19वाँ","23वाँ"],"a":3,"e":"<b>हल:</b><br>चरण 1: अदला-बदली के बाद A, B की पुरानी जगह पर (दाएँ से 15वीं) है और वहाँ वह बाएँ से 20वाँ है।<br>चरण 2: कुल = 20 + 15 − 1 = 34।<br>चरण 3: B अब A की पुरानी जगह पर — बाएँ से 12वाँ।<br>चरण 4: B दाएँ से = 34 − 12 + 1 = 23वाँ।<br>अतः उत्तर = <b>23वाँ</b>"},
    {"q":"25 व्यक्तियों की एक कतार में A आगे से 8वाँ है। B, A के पीछे पाँचवें स्थान पर है। B पीछे से किस स्थान पर है?","o":["18वाँ","14वाँ","12वाँ","13वाँ"],"a":3,"e":"<b>हल:</b><br>चरण 1: A आगे से 8वाँ।<br>चरण 2: B, A के पीछे पाँचवें स्थान पर → B आगे से 8 + 5 = 13वाँ।<br>चरण 3: B पीछे से = 25 − 13 + 1 = 13वाँ।<br>अतः उत्तर = <b>13वाँ</b><br><b>ध्यान दें:</b> B ठीक बीच में है (25 का मध्य 13)।"},
    {"q":"उत्तर की ओर मुँह किए 30 व्यक्तियों की पंक्ति में A बाएँ से 11वाँ है। B, A के दाईं ओर चौथे स्थान पर है और C, B के बाईं ओर तीसरे स्थान पर है। C दाएँ छोर से किस स्थान पर है?","o":["16वाँ","19वाँ","20वाँ","18वाँ"],"a":1,"e":"<b>हल:</b><br>उत्तर की ओर मुख → दायाँ = बाएँ से स्थान बढ़ना।<br>चरण 1: A बाएँ से 11वाँ।<br>चरण 2: B, A के दाईं ओर चौथे स्थान पर → 11 + 4 = 15वाँ (बाएँ से)।<br>चरण 3: C, B के बाईं ओर तीसरे स्थान पर → 15 − 3 = 12वाँ (बाएँ से)।<br>चरण 4: C दाएँ से = 30 − 12 + 1 = 19वाँ।<br>अतः उत्तर = <b>19वाँ</b>"},
    {"q":"50 छात्रों की कक्षा में A की रैंक ऊपर से 10वीं है। B की रैंक A से 5 नीचे है और C की रैंक B से 8 ऊपर है। नीचे से C की रैंक क्या है?","o":["36वीं","43वीं","44वीं","45वीं"],"a":2,"e":"<b>हल:</b><br>चरण 1: A ऊपर से 10वीं रैंक।<br>चरण 2: B, A से 5 नीचे → 10 + 5 = 15वीं।<br>चरण 3: C, B से 8 ऊपर → 15 − 8 = 7वीं (ऊपर से)।<br>चरण 4: नीचे से C = 50 − 7 + 1 = 44वीं।<br>अतः उत्तर = <b>44वीं</b>"},
    {"q":"एक कतार में A आगे से 7वाँ और B पीछे से 5वाँ है। A और B के बीच ठीक 3 बच्चे हैं। कतार में कुल कितने बच्चे हो सकते हैं?","o":["केवल 13","केवल 15","15 या 9","15 या 7"],"a":3,"e":"<b>हल:</b><br>चरण 1: A आगे से 7वाँ, B पीछे से 5वाँ, बीच में 3।<br>चरण 2: स्थिति (i) — B, A के पीछे: B आगे से 7 + 3 + 1 = 11वाँ → कुल = 11 + 5 − 1 = 15।<br>चरण 3: स्थिति (ii) — B, A के आगे: B आगे से 7 − 3 − 1 = 3रा → कुल = 3 + 5 − 1 = 7।<br>जाँच (ii): 7 की कतार में B = 3, A = 7 (अंतिम); बीच 4, 5, 6 = 3 ✓; B पीछे से 7 − 3 + 1 = 5वाँ ✓।<br>अतः उत्तर = <b>15 या 7</b><br><b>ध्यान दें:</b> 9 किसी स्थिति में नहीं आता; केवल एक स्थिति लेने पर \"केवल 15\" की गलती होती है।"},
    {"q":"पाँच व्यक्तियों P, Q, R, S, T के भार अलग-अलग हैं। P, Q से भारी है पर T से हल्का है। R, S से हल्का है पर Q से भारी है। T, S से हल्का है।<br>निम्नलिखित कथनों पर विचार कीजिए —<br>1. S सबसे भारी है।<br>2. R, P से भारी है।<br>निश्चित रूप से सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>चरण 1: P > Q, T > P → T > P > Q।<br>चरण 2: S > R > Q।<br>चरण 3: S > T → S > T > P > Q।<br>चरण 4: दोनों श्रृंखलाएँ: S > T > P > Q और S > R > Q।<br>कथन 1: S, T से और R से भारी, T, P, Q से भी भारी → S सबसे भारी — <b>निश्चित सही</b>।<br>कथन 2: R और P की आपस में कोई तुलना नहीं दी गई (R, T से या P से तुलना नहीं) — <b>निश्चित नहीं</b>।<br>अतः उत्तर = <b>केवल 1</b>"},
    {"q":"पाँच व्यक्तियों P, Q, R, S, T के भार अलग-अलग हैं। P, Q से भारी है पर T से हल्का है। R, S से हल्का है पर Q से भारी है। T, S से हल्का है।<br>सबसे हल्का कौन है?","o":["P","R","Q","T"],"a":2,"e":"<b>हल:</b><br>चरण 1: S > T > P > Q (P > Q, T > P, S > T)।<br>चरण 2: S > R > Q।<br>चरण 3: Q, P से और R से हल्का; P, T, S उससे भी भारी → Q सबसे हल्का।<br>अतः उत्तर = <b>Q</b>"},
    {"q":"पाँच मित्रों A, B, C, D, E की आयु अलग-अलग है। A, B से बड़ा है पर C से छोटा है। D, A से छोटा है पर B से बड़ा है। E, C से बड़ा है।<br>आयु के क्रम में बीच (तीसरे स्थान) पर कौन है?","o":["D","C","B","A"],"a":3,"e":"<b>हल:</b><br>चरण 1: C > A > B (A, B से बड़ा पर C से छोटा)।<br>चरण 2: A > D > B → C > A > D > B।<br>चरण 3: E > C → E > C > A > D > B।<br>चरण 4: तीसरा स्थान (बड़े से) = A (छोटे से गिनें तो भी तीसरा A)।<br>अतः उत्तर = <b>A</b>"},
    {"q":"छह व्यक्तियों P, Q, R, S, T, U की लंबाई अलग-अलग है। P, Q से लंबा है पर R से छोटा है। S, T से छोटा है पर U से लंबा है। R, U से छोटा है।<br>सबसे छोटा (कम लंबाई वाला) कौन है?","o":["U","Q","P","S"],"a":1,"e":"<b>हल:</b><br>चरण 1: R > P > Q।<br>चरण 2: T > S > U।<br>चरण 3: U > R → दोनों जुड़ते हैं: T > S > U > R > P > Q।<br>चरण 4: सबसे छोटा = Q।<br>अतः उत्तर = <b>Q</b>"},
    {"q":"छह व्यक्तियों P, Q, R, S, T, U की लंबाई अलग-अलग है। P, Q से लंबा है पर R से छोटा है। S, T से छोटा है पर U से लंबा है। R, U से छोटा है।<br>सबसे लंबे व्यक्ति से गिनने पर तीसरे स्थान पर कौन है?","o":["U","S","R","P"],"a":0,"e":"<b>हल:</b><br>चरण 1: R > P > Q।<br>चरण 2: T > S > U।<br>चरण 3: U > R → पूरा क्रम: T > S > U > R > P > Q।<br>चरण 4: सबसे लंबे से तीसरा = U।<br>अतः उत्तर = <b>U</b>"},
    {"q":"पाँच व्यक्ति A, B, C, D, E एक पाँच-मंज़िला इमारत की अलग-अलग मंज़िलों पर रहते हैं (सबसे नीचे की मंज़िल = पहली)। B, D से ठीक ऊपर वाली मंज़िल पर रहता है। A, C से ठीक नीचे वाली मंज़िल पर रहता है। C न तो तीसरी और न ही पाँचवीं मंज़िल पर रहता है। D और E दोनों पहली मंज़िल पर नहीं रहते। B सबसे ऊपरी मंज़िल पर नहीं रहता।<br>सबसे ऊपरी मंज़िल पर कौन रहता है?","o":["C","B","E","D"],"a":2,"e":"<b>हल:</b><br>मंज़िल 1 (नीचे) से 5 (ऊपर)।<br>चरण 1: A, C के ठीक नीचे → C ≠ 1; C न 3 न 5 → C = 2 या 4।<br>चरण 2: C = 4 लें → A = 3; बची मंज़िलें 1, 2, 5। D, E पहली पर नहीं → B = 1, पर B = D + 1 के लिए D = 0 — असंभव ✗।<br>चरण 3: C = 2 → A = 1; बची 3, 4, 5। B = D + 1 और B ≠ 5 → D = 3, B = 4; E = 5 ✓।<br>अंतिम व्यवस्था:<br>5 — E<br>4 — B<br>3 — D<br>2 — C<br>1 — A<br>अतः सबसे ऊपर = <b>E</b>"},
    {"q":"पाँच व्यक्ति A, B, C, D, E एक पाँच-मंज़िला इमारत की अलग-अलग मंज़िलों पर रहते हैं (सबसे नीचे की मंज़िल = पहली)। B, D से ठीक ऊपर वाली मंज़िल पर रहता है। A, C से ठीक नीचे वाली मंज़िल पर रहता है। C न तो तीसरी और न ही पाँचवीं मंज़िल पर रहता है। D और E दोनों पहली मंज़िल पर नहीं रहते। B सबसे ऊपरी मंज़िल पर नहीं रहता।<br>C और B के बीच वाली मंज़िल पर कौन रहता है?","o":["E","कोई नहीं","A","D"],"a":3,"e":"<b>हल:</b><br>चरण 1: C = 2 या 4 (C ≠ 1 क्योंकि A उसके ठीक नीचे है; C ≠ 3, 5)।<br>चरण 2: C = 4 → A = 3; बची 1, 2, 5; D, E पहली पर नहीं → B = 1 और D = 0 — असंभव ✗।<br>चरण 3: C = 2 → A = 1; D = 3, B = 4 (B ≠ 5), E = 5 ✓।<br>व्यवस्था: 5-E, 4-B, 3-D, 2-C, 1-A<br>चरण 4: C (2) और B (4) के बीच मंज़िल 3 = D।<br>अतः उत्तर = <b>D</b>"},
    {"q":"छह व्यक्ति A, B, C, D, E, F एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं। B बाएँ छोर पर है। C, E के ठीक दाएँ है। D और C के बीच ठीक दो व्यक्ति बैठे हैं। F, A के ठीक बाएँ है। A दाएँ छोर पर नहीं है।<br>दाएँ छोर पर कौन बैठा है?","o":["A","D","F","C"],"a":1,"e":"<b>हल:</b><br>उत्तर की ओर मुख → स्थान 1 (बायाँ) से 6 (दायाँ)।<br>चरण 1: B = 1।<br>चरण 2: जोड़े — \"E C\" (C, E के ठीक दाएँ) और \"F A\" (F, A के ठीक बाएँ); D और C के बीच 2 व्यक्ति → |D − C| = 3।<br>चरण 3: D = 6 → C = 3, E = 2; F A = 4, 5 ✓ (A दाएँ छोर पर नहीं ✓)।<br>चरण 4: अन्य स्थितियाँ — D = 2 → C = 5, E = 4, बचे 3 व 6 (F A साथ नहीं) ✗; D = 3 → C = 6, E = 5, बचे 2 व 4 ✗; D = 4 या 5 → C = 1 या 2, जो B/E से टकराता है ✗।<br>अंतिम क्रम: <b>B, E, C, F, A, D</b><br>अतः दाएँ छोर पर = <b>D</b>"},
    {"q":"छह व्यक्ति A, B, C, D, E, F एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं। B बाएँ छोर पर है। C, E के ठीक दाएँ है। D और C के बीच ठीक दो व्यक्ति बैठे हैं। F, A के ठीक बाएँ है। A दाएँ छोर पर नहीं है।<br>बाएँ से तीसरे स्थान पर कौन बैठा है?","o":["F","A","C","E"],"a":2,"e":"<b>हल:</b><br>पिछले प्रश्न की तरह व्यवस्था बनाएँ (स्थान 1 = बायाँ):<br>चरण 1: B = 1; \"E C\" और \"F A\" जोड़े; |D − C| = 3; A ≠ 6।<br>चरण 2: एकमात्र संभव: D = 6, C = 3, E = 2, F = 4, A = 5।<br>अंतिम क्रम: <b>B, E, C, F, A, D</b><br>चरण 3: बाएँ से तीसरा = C।<br>अतः उत्तर = <b>C</b>"},
    {"q":"छह व्यक्ति A, B, C, D, E, F एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं। B बाएँ छोर पर है। C, E के ठीक दाएँ है। D और C के बीच ठीक दो व्यक्ति बैठे हैं। F, A के ठीक बाएँ है। A दाएँ छोर पर नहीं है।<br>E और A के बीच कितने व्यक्ति बैठे हैं?","o":["1","2","3","0"],"a":1,"e":"<b>हल:</b><br>चरण 1: व्यवस्था (बाएँ → दाएँ): B, E, C, F, A, D (B छोर पर; E C जोड़ा; F A जोड़ा; D और C के बीच F, A)।<br>चरण 2: E = स्थान 2, A = स्थान 5।<br>चरण 3: बीच में = 5 − 2 − 1 = 2 (C और F)।<br>अतः उत्तर = <b>2</b>"},
    {"q":"आठ मित्र A, B, C, D, E, F, G, H एक वृत्त में केंद्र की ओर मुँह करके बैठे हैं। A, E के ठीक सामने है। B, A के बाएँ से दूसरे स्थान पर है। E, C के ठीक बाएँ है। D, C के ठीक सामने है। F, D का निकटतम पड़ोसी है। G, A के ठीक बाएँ है।<br>G के ठीक सामने कौन बैठा है?","o":["F","E","H","C"],"a":2,"e":"<b>हल:</b><br>केंद्र की ओर मुख होने पर किसी का \"बायाँ\" = वृत्त में दक्षिणावर्त अगला स्थान। स्थानों को दक्षिणावर्त क्रमांकित करें।<br>चरण 1: A = 1; E, A के ठीक सामने (8 में 4 दूर) → E = 5।<br>चरण 2: G, A के ठीक बाएँ → G = 2; B, A के बाएँ से दूसरा → B = 3।<br>चरण 3: E, C के ठीक बाएँ → C का दक्षिणावर्त अगला E → C = 4।<br>चरण 4: D, C के सामने → D = 8।<br>चरण 5: F, D का पड़ोसी → D (8) के पड़ोसी 7 और 1 (A) → F = 7; बचा H = 6।<br>दक्षिणावर्त क्रम: <b>A(1), G(2), B(3), C(4), E(5), H(6), F(7), D(8)</b><br>चरण 6: G (2) के सामने = 2 + 4 = 6 = H।<br>अतः उत्तर = <b>H</b>"},
    {"q":"आठ मित्र A, B, C, D, E, F, G, H एक वृत्त में केंद्र की ओर मुँह करके बैठे हैं। A, E के ठीक सामने है। B, A के बाएँ से दूसरे स्थान पर है। E, C के ठीक बाएँ है। D, C के ठीक सामने है। F, D का निकटतम पड़ोसी है। G, A के ठीक बाएँ है।<br>F के ठीक बाएँ कौन बैठा है?","o":["A","D","H","E"],"a":1,"e":"<b>हल:</b><br>केंद्र की ओर मुख होने पर किसी का \"बायाँ\" = वृत्त में दक्षिणावर्त अगला स्थान। स्थानों को दक्षिणावर्त क्रमांकित करें।<br>चरण 1: A = 1, E = 5 (सामने), G = 2, B = 3।<br>चरण 2: E, C के ठीक बाएँ → C = 4; D, C के सामने → D = 8।<br>चरण 3: F, D का पड़ोसी → F = 7 (स्थान 1 पर A है); H = 6।<br>दक्षिणावर्त क्रम: <b>A, G, B, C, E, H, F, D</b><br>चरण 4: F (7) का ठीक बायाँ = दक्षिणावर्त अगला = 8 = D।<br>अतः उत्तर = <b>D</b>"},
    {"q":"छह व्यक्ति P, Q, R, S, T, U एक वृत्त में केंद्र से बाहर की ओर मुँह करके बैठे हैं। P, S के ठीक सामने है। Q, P के ठीक बाएँ है। R, Q के ठीक सामने है। T, S के ठीक दाएँ नहीं है।<br>U के ठीक बाएँ कौन बैठा है?","o":["P","T","Q","S"],"a":3,"e":"<b>हल:</b><br>बाहर की ओर मुख होने पर दिशाएँ उलट जाती हैं — \"बायाँ\" = वृत्त में वामावर्त अगला स्थान। स्थानों 1–6 को वामावर्त क्रमांकित करें।<br>चरण 1: P = 1; S, P के सामने → S = 4।<br>चरण 2: Q, P के ठीक बाएँ → Q = 2।<br>चरण 3: R, Q के सामने → R = 5।<br>चरण 4: बचे 3 और 6। S (4) का ठीक दायाँ = 3; T वहाँ नहीं → T = 6, U = 3।<br>वामावर्त क्रम: <b>P(1), Q(2), U(3), S(4), R(5), T(6)</b><br>चरण 5: U (3) का ठीक बायाँ = वामावर्त अगला = 4 = S।<br>अतः उत्तर = <b>S</b>"},
    {"q":"छह व्यक्ति P, Q, R, S, T, U एक वृत्त में केंद्र से बाहर की ओर मुँह करके बैठे हैं। P, S के ठीक सामने है। Q, P के ठीक बाएँ है। R, Q के ठीक सामने है। T, S के ठीक दाएँ नहीं है।<br>T किन दो व्यक्तियों के बीच बैठा है?","o":["P और R","S और U","Q और P","R और S"],"a":0,"e":"<b>हल:</b><br>बाहर की ओर मुख → \"बायाँ\" = वामावर्त अगला; स्थान 1–6 वामावर्त।<br>चरण 1: P = 1, S = 4 (सामने), Q = 2 (P के बाएँ), R = 5 (Q के सामने)।<br>चरण 2: S का दायाँ = 3; T वहाँ नहीं → T = 6, U = 3।<br>क्रम: <b>P(1), Q(2), U(3), S(4), R(5), T(6)</b><br>चरण 3: T (6) के पड़ोसी = 5 (R) और 1 (P)।<br>अतः उत्तर = <b>P और R</b>"},
    {"q":"पाँच व्यक्ति V, W, X, Y, Z एक पंक्ति में दक्षिण की ओर मुँह करके खड़े हैं। X ठीक बीच में है। V, X के ठीक दाएँ है। Z पूर्वी छोर पर है। W, V के ठीक बगल में नहीं है।<br>पश्चिमी छोर पर कौन खड़ा है?","o":["Z","Y","V","W"],"a":1,"e":"<b>हल:</b><br>दक्षिण की ओर मुख → उनका दायाँ = पश्चिम, बायाँ = पूर्व। पंक्ति को पश्चिम से पूर्व स्थान 1–5 लिखें।<br>चरण 1: X बीच में → X = 3।<br>चरण 2: V, X के ठीक दाएँ (पश्चिम की ओर) → V = 2।<br>चरण 3: Z पूर्वी छोर → Z = 5।<br>चरण 4: बचे 1 और 4; W, V (2) के बगल नहीं → W ≠ 1 → W = 4, Y = 1।<br>पश्चिम → पूर्व: <b>Y, V, X, W, Z</b><br>अतः पश्चिमी छोर पर = <b>Y</b><br><b>ध्यान दें:</b> दक्षिण मुख में दायाँ = पश्चिम; इसे पूर्व मान लेने पर पूरी व्यवस्था उलट जाती है।"},
    {"q":"पाँच व्यक्ति V, W, X, Y, Z एक पंक्ति में दक्षिण की ओर मुँह करके खड़े हैं। X ठीक बीच में है। V, X के ठीक दाएँ है। Z पूर्वी छोर पर है। W, V के ठीक बगल में नहीं है।<br>W के ठीक दाएँ कौन खड़ा है?","o":["Y","Z","V","X"],"a":3,"e":"<b>हल:</b><br>दक्षिण मुख → दायाँ = पश्चिम। स्थान 1–5 पश्चिम से पूर्व।<br>चरण 1: X = 3; V = 2 (X के दाएँ = पश्चिम); Z = 5 (पूर्वी छोर)।<br>चरण 2: W, V के बगल नहीं → W = 4, Y = 1।<br>पश्चिम → पूर्व: <b>Y, V, X, W, Z</b><br>चरण 3: W (4) का ठीक दायाँ = पश्चिम की ओर अगला = 3 = X।<br>अतः उत्तर = <b>X</b>"},
    {"q":"छह व्यक्ति दो समानांतर पंक्तियों में 3-3 करके बैठे हैं। पंक्ति-1 में P, Q, R दक्षिण की ओर मुँह करके और पंक्ति-2 में X, Y, Z उत्तर की ओर मुँह करके बैठे हैं, जिससे प्रत्येक व्यक्ति दूसरी पंक्ति के किसी एक व्यक्ति के ठीक सामने है। Q अपनी पंक्ति के बीच में है। R, Q के ठीक दाएँ है। Z, P के ठीक सामने है। X, Q के ठीक सामने नहीं है।<br>X के ठीक सामने कौन बैठा है?","o":["R","P","Q","कोई नहीं"],"a":0,"e":"<b>हल:</b><br>पंक्ति-1 दक्षिण मुख (दायाँ = पश्चिम); पंक्ति-2 उत्तर मुख। स्थानों को पश्चिम से पूर्व 1, 2, 3 लिखें।<br>चरण 1: Q बीच में → Q = 2।<br>चरण 2: R, Q के ठीक दाएँ (पश्चिम) → R = 1; P = 3।<br>पंक्ति-1 (पश्चिम → पूर्व): R, Q, P<br>चरण 3: Z, P के सामने → Z = 3।<br>चरण 4: X, Q (2) के सामने नहीं → X = 1, Y = 2।<br>पंक्ति-2 (पश्चिम → पूर्व): X, Y, Z<br>चरण 5: X (1) के सामने = R।<br>अतः उत्तर = <b>R</b>"},
    {"q":"पाँच मित्र A, B, C, D, E एक वृत्त में केंद्र की ओर मुँह करके बैठे हैं। C, A के ठीक बाएँ है। B, C और D के बीच है। E, A के ठीक दाएँ है। D के ठीक बाएँ कौन है?","o":["B","A","E","C"],"a":2,"e":"<b>हल:</b><br>केंद्र की ओर मुख होने पर किसी का \"बायाँ\" = वृत्त में दक्षिणावर्त अगला स्थान। स्थानों को दक्षिणावर्त क्रमांकित करें।<br>चरण 1: A = 1; C, A के ठीक बाएँ → C = 2।<br>चरण 2: E, A के ठीक दाएँ → दाएँ = वामावर्त अगला → E = 5।<br>चरण 3: बचे 3 और 4; B, C और D के बीच → B = 3, D = 4।<br>दक्षिणावर्त क्रम: <b>A(1), C(2), B(3), D(4), E(5)</b><br>चरण 4: D (4) का ठीक बायाँ = दक्षिणावर्त अगला = 5 = E।<br>अतः उत्तर = <b>E</b>"}
  ]
});
